-- Illinois had fifteen stops, eight of them in Casey.
--
-- Five dropped as duplicates, four of which are Casey's objects arriving again
-- under different spellings — Wind Chime against Windchime, World's against
-- Worlds. The fifth is the Paul Bunyon Hot Dog Statue at Atlanta, zero metres
-- from the Paul Bunyan Statue already here. Same statue, and the local
-- spelling really is Bunyon.
--
-- Thirteen Route 66 stops nearly did not parse at all: their category was
-- "route-66", and the pattern reading category names allowed letters and
-- hyphens but not digits.
--
-- Tennessee, Alabama and Mississippi are Central time; so are Illinois,
-- Wisconsin and Louisiana. No county exceptions in any of the six.
--
-- 145 stops.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Couch Tomb', 'couch-tomb', 'weird-history', 41.91293, -87.63142, 'Chicago', 'IL', 'An above-ground 1838 tomb left conspicuously standing inside Lincoln Park, a remnant of the cemetery that once occupied the grounds.', 'open', 'https://www.chicagoparkdistrict.com/parks-facilities/couch-tomb-artwork', null, 'America/Chicago', now()),
  ('Jane Addams Hull-House Museum', 'jane-addams-hull-house-museum', 'haunted', 41.87165, -87.6474, 'Chicago', 'IL', 'The preserved Hull-House complex combines reform-era history with long-running stories of apparitions and the mansion''s famously unsettling Devil Baby legend.', 'limited', 'https://www.hullhousemuseum.org/', null, 'America/Chicago', now()),
  ('International Museum of Surgical Science', 'international-museum-of-surgical-science', 'museums', 41.91031, -87.62661, 'Chicago', 'IL', 'A mansion packed with antique surgical instruments, anatomical art, early medical equipment, and enough historical medicine to make this a natural OddWay stop.', 'limited', 'https://imss.org/', null, 'America/Chicago', now()),
  ('Medieval Torture Museum', 'medieval-torture-museum', 'museums', 41.88478, -87.62775, 'Chicago', 'IL', 'A large collection of torture-device reconstructions and dark historical displays in downtown Chicago, presented as an immersive walk-through museum.', 'limited', 'https://medievaltorturemuseum.com/chicago/', null, 'America/Chicago', now()),
  ('U-505 Submarine', 'u-505-submarine', 'roadside-oddities', 41.79188, -87.58125, 'Chicago', 'IL', 'The only German U-boat captured by the United States during World War II is displayed indoors beneath the Museum of Science and Industry.', 'limited', 'https://www.msichicago.org/explore/whats-here/exhibits/u-505-submarine/', null, 'America/Chicago', now()),
  ('Congress Plaza Hotel', 'congress-plaza-hotel', 'haunted', 41.87508, -87.62484, 'Chicago', 'IL', 'One of Chicago''s best-known haunted hotels, tied to decades of ghost stories, unexplained sightings, and dark tales surrounding its long history.', 'limited', 'https://www.congressplazahotel.com/', null, 'America/Chicago', now()),
  ('Iroquois Theatre Fire Site / Death Alley', 'iroquois-theatre-fire-site-death-alley', 'weird-history', 41.88485, -87.62887, 'Chicago', 'IL', 'The area behind today''s Nederlander Theatre marks the 1903 Iroquois Theatre disaster, where more than 600 people died and ghost stories still linger.', 'roadside', 'https://www.choosechicago.com/blog/tours-attractions/chicago-most-haunted-places/', null, 'America/Chicago', now()),
  ('Biograph Theater / John Dillinger Site', 'biograph-theater-john-dillinger-site', 'weird-history', 41.92652, -87.6498, 'Chicago', 'IL', 'Outside this historic theater, federal agents shot bank robber John Dillinger in 1934 after he left a movie screening.', 'roadside', 'https://www.fbi.gov/history/famous-cases/john-dillinger', null, 'America/Chicago', now()),
  ('Green Mill Cocktail Lounge', 'green-mill-cocktail-lounge', 'weird-history', 41.96918, -87.65989, 'Chicago', 'IL', 'A Prohibition-era jazz club strongly associated with Al Capone''s Chicago, complete with old booths, tunnels lore, and a remarkably preserved atmosphere.', 'limited', 'https://greenmilljazz.com/', null, 'America/Chicago', now()),
  ('Chicago Water Tower', 'chicago-water-tower', 'haunted', 41.89717, -87.62444, 'Chicago', 'IL', 'One of the few structures to survive the Great Chicago Fire, later wrapped into local ghost stories involving a spectral hanging figure.', 'open', 'https://www.choosechicago.com/blog/tours-attractions/chicago-most-haunted-places/', null, 'America/Chicago', now()),
  ('Nuclear Energy Sculpture / Chicago Pile-1 Site', 'nuclear-energy-sculpture-chicago-pile-1-site', 'weird-history', 41.79249, -87.60106, 'Chicago', 'IL', 'Henry Moore''s looming sculpture marks the site where scientists achieved the first controlled, self-sustaining nuclear chain reaction in 1942.', 'open', 'https://www.nps.gov/places/site-of-the-first-self-sustaining-controlled-nuclear-chain-reaction.htm', null, 'America/Chicago', now()),
  ('Fountain of Time', 'fountain-of-time', 'roadside-oddities', 41.78675, -87.60775, 'Chicago', 'IL', 'A massive procession of 100 human figures marches past Father Time in one of the city''s strangest and most imposing public sculptures.', 'open', 'https://www.chicagoparkdistrict.com/parks-facilities/washington-fountain-time', null, 'America/Chicago', now()),
  ('Oz Park', 'oz-park', 'roadside-oddities', 41.9206, -87.64567, 'Chicago', 'IL', 'A neighborhood park filled with permanent bronze Wizard of Oz character statues, including Dorothy, Tin Man, Scarecrow, and Cowardly Lion.', 'open', 'https://www.chicagoparkdistrict.com/parks-facilities/oz-park', null, 'America/Chicago', now()),
  ('Shit Fountain', 'shit-fountain', 'roadside-oddities', 41.89972, -87.67463, 'Chicago', 'IL', 'A deliberately crude bronze coil created by artist Jerzy Kenar as a pointed response to dog owners who refused to clean up after pets.', 'roadside', 'https://www.atlasobscura.com/places/shit-fountain', null, 'America/Chicago', now()),
  ('Eternal Silence', 'eternal-silence', 'weird-history', 41.9588, -87.6615, 'Chicago', 'IL', 'A hooded bronze figure looms over the Graves family plot in Graceland Cemetery, producing one of Chicago''s most unnerving funerary monuments.', 'limited', 'https://www.gracelandcemetery.org/', null, 'America/Chicago', now()),
  ('Inez Clarke Memorial', 'inez-clarke-memorial', 'folklore', 41.95789, -87.66197, 'Chicago', 'IL', 'This life-sized statue of a young girl in Graceland Cemetery inspired persistent stories that the figure vanishes during thunderstorms.', 'limited', 'https://www.gracelandcemetery.org/tour-map-biographies/', null, 'America/Chicago', now()),
  ('Schoenhofen Pyramid Mausoleum', 'schoenhofen-pyramid-mausoleum', 'weird-history', 41.95959, -87.65954, 'Chicago', 'IL', 'An Egyptian Revival pyramid mausoleum with a sphinx-like entrance makes this one of the most visually unusual tombs in Graceland Cemetery.', 'limited', 'https://www.gracelandcemetery.org/', null, 'America/Chicago', now()),
  ('Getty Tomb', 'getty-tomb', 'weird-history', 41.96111, -87.66111, 'Chicago', 'IL', 'Designed by Louis Sullivan, this striking mausoleum uses intricate geometric ornament unlike almost anything else in Chicago''s cemetery landscape.', 'limited', 'https://www.gracelandcemetery.org/', null, 'America/Chicago', now()),
  ('Haymarket Martyrs'' Monument', 'haymarket-martyrs-monument', 'weird-history', 41.8698, -87.81977, 'Forest Park', 'IL', 'A National Historic Landmark monument over the graves of men executed after the Haymarket affair, central to international labor history.', 'limited', 'https://www.nps.gov/places/haymarket-martyrs-monument.htm', null, 'America/Chicago', now()),
  ('Resurrection Cemetery / Resurrection Mary', 'resurrection-cemetery-resurrection-mary', 'haunted', 41.75797, -87.82741, 'Justice', 'IL', 'The cemetery gates are inseparable from the legend of Resurrection Mary, the hitchhiking ghost said to disappear near Archer Avenue.', 'limited', 'https://www.enjoyillinois.com/plan-your-trip/road-trip-itineraries/haunted-chicago/', null, 'America/Chicago', now()),
  ('Bachelor''s Grove Cemetery', 'bachelors-grove-cemetery', 'haunted', 41.63089, -87.77072, 'Midlothian', 'IL', 'A tiny abandoned pioneer cemetery deep in the forest preserve, famous for decades of phantom-house, ghost-car, and apparition stories.', 'open', 'https://fpdcc.com/', null, 'America/Chicago', now()),
  ('Al Capone Grave', 'al-capone-grave', 'weird-history', 41.86294, -87.90642, 'Hillside', 'IL', 'The grave of Chicago crime boss Al Capone sits in Mount Carmel Cemetery among other figures connected to the city''s organized-crime history.', 'limited', 'https://www.catholiccemeterieschicago.org/', null, 'America/Chicago', now()),
  ('Bahá''í House of Worship', 'bah-house-of-worship', 'roadside-oddities', 42.07444, -87.68444, 'Wilmette', 'IL', 'One of only a handful of continental Bahá''í temples worldwide, with an elaborate white dome covered in intricate symbols and lace-like ornament.', 'open', 'https://www.bahai.us/bahai-temple/', null, 'America/Chicago', now()),
  ('American Toby Jug Museum', 'american-toby-jug-museum', 'museums', 42.03459, -87.67977, 'Evanston', 'IL', 'Thousands of figural ceramic jugs fill a museum devoted almost entirely to Toby and character jugs, from historic examples to modern pop culture.', 'limited', 'https://www.tobyjugmuseum.com/', null, 'America/Chicago', now()),
  ('Leaning Tower of Niles', 'leaning-tower-of-niles', 'roadside-oddities', 42.01242, -87.78406, 'Niles', 'IL', 'A half-scale 1930s recreation of Italy''s Leaning Tower of Pisa stands beside a suburban YMCA complex as one of Chicagoland''s classic oddities.', 'open', 'https://www.vniles.com/883/Leaning-Tower-of-Niles', null, 'America/Chicago', now()),
  ('Busy Beaver Button Museum', 'busy-beaver-button-museum', 'museums', 41.91719, -87.71227, 'Chicago', 'IL', 'A working button factory houses a free museum tracing more than a century of pin-back buttons, slogans, politics, advertising, and novelty design.', 'limited', 'https://www.busybeaver.net/button-museum/', null, 'America/Chicago', now()),
  ('Woolly Mammoth Antiques & Oddities', 'woolly-mammoth-antiques-oddities', 'roadside-oddities', 41.97608, -87.66898, 'Chicago', 'IL', 'Taxidermy, bones, medical pieces, strange antiques, and unconventional art make this long-running Andersonville shop feel more cabinet of curiosities than store.', 'limited', 'https://www.woollymammothchicago.com/', null, 'America/Chicago', now()),
  ('Pullman National Historical Park Visitor Center', 'pullman-national-historical-park-visitor-center', 'weird-history', 41.69429, -87.60874, 'Chicago', 'IL', 'The preserved company town tells an unusually complete story of industrial paternalism, railroad sleeping cars, labor conflict, and the Pullman Strike.', 'limited', 'https://www.nps.gov/pull/planyourvisit/visitorcenters.htm', null, 'America/Chicago', now()),
  ('Chicago Portage National Historic Site', 'chicago-portage-national-historic-site', 'weird-history', 41.80487, -87.80543, 'Lyons', 'IL', 'This quiet forest-preserve site marks the ancient portage that ultimately helped determine why Chicago grew where it did.', 'open', 'https://fpdcc.com/places/locations/chicago-portage-national-historic-site/', null, 'America/Chicago', now()),
  ('Red Lion Pub', 'red-lion-pub', 'haunted', 41.92632, -87.65046, 'Chicago', 'IL', 'A British-style pub near the Biograph is associated with stories of phantom footsteps, shadowy figures, and other alleged paranormal activity.', 'limited', 'https://redlionchicago.com/', null, 'America/Chicago', now()),
  ('Volo Museum', 'volo-museum', 'museums', 42.32687, -88.17145, 'Volo', 'IL', 'A sprawling collection of famous movie cars, bizarre customs, vintage machines, animatronics, military pieces, and oversized roadside-style displays.', 'limited', 'https://www.volofun.com/', null, 'America/Chicago', now()),
  ('Historic Auto Attractions', 'historic-auto-attractions', 'museums', 42.46141, -89.01412, 'Roscoe', 'IL', 'An enormous private museum mixing celebrity vehicles, presidential artifacts, movie props, military displays, crime-history objects, and other eclectic Americana.', 'limited', 'https://historicautoattractions.com/', null, 'America/Chicago', now()),
  ('Burpee Museum of Natural History', 'burpee-museum-of-natural-history', 'museums', 42.2773, -89.08817, 'Rockford', 'IL', 'Home of Jane, one of the world''s best-preserved juvenile Tyrannosaurus rex specimens, along with fossils and unusual regional natural-history collections.', 'limited', 'https://burpee.org/', null, 'America/Chicago', now()),
  ('Tinker Swiss Cottage Museum', 'tinker-swiss-cottage-museum', 'haunted', 42.26528, -89.10194, 'Rockford', 'IL', 'A remarkable Swiss-inspired Victorian home whose preserved rooms, family artifacts, and long-running ghost stories make it unusually atmospheric.', 'limited', 'https://www.tinkercottage.com/', null, 'America/Chicago', now()),
  ('Rockmen Guardians', 'rockmen-guardians', 'roadside-oddities', 42.28056, -89.07655, 'Rockford', 'IL', 'Large stone-and-concrete humanoid figures stand along the Rock River like strange sentinels, making an easy, surreal photo stop.', 'open', 'https://www.enjoyillinois.com/', null, 'America/Chicago', now()),
  ('Sock Monkey Museum', 'sock-monkey-museum', 'museums', 42.1784, -87.9979, 'Long Grove', 'IL', 'More than 2,000 sock monkeys and related displays fill this specialty museum devoted to the humble red-heel folk toy.', 'limited', 'https://sockmonkeymuseum.com/', null, 'America/Chicago', now()),
  ('Black Hawk Statue / Eternal Indian', 'black-hawk-statue-eternal-indian', 'roadside-oddities', 42.03416, -89.33321, 'Oregon', 'IL', 'Lorado Taft''s colossal concrete figure towers above the Rock River at Lowden State Park; ongoing preservation work can affect close viewing.', 'limited', 'https://dnr.illinois.gov/parks/park.lowden.html', null, 'America/Chicago', now()),
  ('John Deere Historic Site', 'john-deere-historic-site', 'weird-history', 41.89608, -89.41592, 'Grand Detour', 'IL', 'The reconstructed blacksmith shop and archaeological remains mark where John Deere developed the polished steel plow that transformed Midwestern farming.', 'limited', 'https://www.deere.com/en/connect-with-john-deere/visit-john-deere/historic-site/', null, 'America/Chicago', now()),
  ('De Immigrant Windmill', 'de-immigrant-windmill', 'roadside-oddities', 41.86715, -90.16846, 'Fulton', 'IL', 'A full-size working Dutch windmill built in the Netherlands and reassembled on the Mississippi Riverfront, complete with traditional milling machinery.', 'open', 'https://www.cityoffulton.us/', null, 'America/Chicago', now()),
  ('Heritage Canyon', 'heritage-canyon', 'weird-history', 41.87717, -90.16465, 'Fulton', 'IL', 'An abandoned quarry transformed into a wooded village of reconstructed historic buildings, machinery, and small-town scenes.', 'open', 'https://www.cityoffulton.us/', null, 'America/Chicago', now()),
  ('Raven''s Grin Inn', 'ravens-grin-inn', 'haunted', 42.10053, -89.98004, 'Mount Carroll', 'IL', 'A former hotel converted by artist Jim Warfield into an eccentric handmade haunted house full of secret passages, mechanical gags, and surreal rooms.', 'limited', 'https://www.atlasobscura.com/places/ravens-grin-inn', null, 'America/Chicago', now()),
  ('Dowling House', 'dowling-house', 'roadside-oddities', 42.41711, -90.42699, 'Galena', 'IL', 'Built in 1826, this rough limestone trading house is one of Galena''s oldest surviving structures and feels dramatically older than the city around it.', 'limited', 'https://www.galenahistory.org/', null, 'America/Chicago', now()),
  ('DeSoto House Hotel', 'desoto-house-hotel', 'haunted', 42.41467, -90.42968, 'Galena', 'IL', 'Illinois'' oldest operating hotel hosted Abraham Lincoln and Ulysses S. Grant and carries a substantial body of guest and staff ghost lore.', 'limited', 'https://desotohouse.com/hotel-history/', null, 'America/Chicago', now()),
  ('Belvedere Mansion', 'belvedere-mansion', 'weird-history', 42.40964, -90.42855, 'Galena', 'IL', 'A lavish 1857 mansion filled with period furnishings and film memorabilia, including pieces associated with Gone with the Wind.', 'limited', 'https://www.belvederemansionandgardens.com/', null, 'America/Chicago', now()),
  ('Old Market House State Historic Site', 'old-market-house-state-historic-site', 'weird-history', 42.41575, -90.42739, 'Galena', 'IL', 'A preserved 1845 market building now interprets Galena''s boom years, including mining, river commerce, and Ulysses S. Grant-era history.', 'limited', 'https://dnrhistoric.illinois.gov/experience/sites/northwest/old-market-house.html', null, 'America/Chicago', now()),
  ('Casper Bluff Land & Water Reserve', 'casper-bluff-land-water-reserve', 'weird-history', 42.362, -90.43, 'Galena', 'IL', 'A Mississippi River bluff preserve containing Native American burial mounds, including a rare thunderbird-shaped effigy mound.', 'open', 'https://jdcf.org/', null, 'America/Chicago', now()),
  ('Apple River Fort State Historic Site', 'apple-river-fort-state-historic-site', 'weird-history', 42.31851, -90.21275, 'Elizabeth', 'IL', 'A reconstruction of the small fort attacked during the Black Hawk War, with self-guided grounds and periodic living-history programming.', 'open', 'https://www.appleriverfort.org/', null, 'America/Chicago', now()),
  ('Little Cubs Field', 'little-cubs-field', 'roadside-oddities', 42.28775, -89.64091, 'Freeport', 'IL', 'A meticulously scaled neighborhood baseball field recreates Wrigley Field''s ivy, scoreboard, rooftops, and marquee in miniature.', 'open', 'https://www.littlecubsfield.com/', null, 'America/Chicago', now()),
  ('Illinois Railway Museum', 'illinois-railway-museum', 'roadside-oddities', 42.22643, -88.52617, 'Union', 'IL', 'The country''s largest railway museum preserves an enormous operating collection of locomotives, streetcars, interurbans, and historic transit equipment.', 'limited', 'https://www.irm.org/', null, 'America/Chicago', now()),
  ('Egyptian Theatre', 'egyptian-theatre', 'roadside-oddities', 41.93118, -88.75278, 'DeKalb', 'IL', 'A rare 1929 Egyptian Revival movie palace filled with scarabs, pharaoh motifs, hieroglyphic decoration, and an atmospheric auditorium.', 'limited', 'https://egyptiantheatre.org/', null, 'America/Chicago', now()),
  ('Vintage Wings & Wheels Museum', 'vintage-wings-wheels-museum', 'museums', 42.3255, -88.83953, 'Poplar Grove', 'IL', 'A small airfield museum pairs vintage aircraft with antique cars, motorcycles, engines, uniforms, and regional aviation history.', 'limited', 'https://www.wingsandwheelsmuseum.org/', null, 'America/Chicago', now()),
  ('Norma Jean Circus Elephant Monument', 'norma-jean-circus-elephant-monument', 'roadside-oddities', 40.93998, -90.94931, 'Oquawka', 'IL', 'A large stone monument marks the 1972 death of Norma Jean, a circus elephant killed by lightning while tethered in town.', 'open', 'https://www.hmdb.org/', null, 'America/Chicago', now()),
  ('Rock Island Arsenal Museum', 'rock-island-arsenal-museum', 'museums', 41.51781, -90.54038, 'Rock Island Arsenal', 'IL', 'One of the U.S. Army''s oldest museums traces weapons, manufacturing, and the history of the active Rock Island Arsenal.', 'limited', 'https://www.army.mil/arsenal/', null, 'America/Chicago', now()),
  ('Black Hawk State Historic Site', 'black-hawk-state-historic-site', 'weird-history', 41.46698, -90.57236, 'Rock Island', 'IL', 'Wooded trails and museum exhibits interpret Sauk and Meskwaki history at the former location of the village associated with Black Hawk.', 'open', 'https://dnr.illinois.gov/parks/park.blackhawk.html', null, 'America/Chicago', now()),
  ('Colonel Davenport House', 'colonel-davenport-house', 'haunted', 41.51939, -90.55636, 'Rock Island Arsenal', 'IL', 'The 1830s home of fur trader George Davenport stands on Arsenal Island, where his 1845 murder became part of local ghost lore.', 'limited', 'https://www.davenporthouse.org/', null, 'America/Chicago', now()),
  ('Bishop Hill Colony Church', 'bishop-hill-colony-church', 'weird-history', 41.20031, -90.11889, 'Bishop Hill', 'IL', 'A surviving 1848 building from the Swedish religious commune that founded Bishop Hill, preserving the town''s unusual communal-colony history.', 'limited', 'https://dnrhistoric.illinois.gov/experience/sites/northwest/bishop-hill.html', null, 'America/Chicago', now()),
  ('Steeple Building Museum', 'steeple-building-museum', 'weird-history', 41.20049, -90.11861, 'Bishop Hill', 'IL', 'The 1854 Steeple Building now houses exhibits and artifacts from Bishop Hill''s once-thriving Swedish communal colony.', 'limited', 'https://bishophillheritage.org/', null, 'America/Chicago', now()),
  ('Wyatt Earp Birthplace', 'wyatt-earp-birthplace', 'weird-history', 40.90796, -90.64487, 'Monmouth', 'IL', 'The restored birthplace of Wyatt Earp interprets the Illinois childhood of the future lawman before the family moved west.', 'limited', 'https://www.wyattearp.org/history/', null, 'America/Chicago', now()),
  ('Carl Sandburg State Historic Site', 'carl-sandburg-state-historic-site', 'roadside-oddities', 40.93628, -90.36595, 'Galesburg', 'IL', 'The poet''s tiny birthplace, museum, grave, and memorial grounds preserve the Midwestern roots of one of America''s most recognizable literary voices.', 'limited', 'https://dnrhistoric.illinois.gov/experience/sites/northwest/carl-sandburg.html', null, 'America/Chicago', now()),
  ('M65 Atomic Cannon', 'm65-atomic-cannon', 'roadside-oddities', 41.5177, -90.54037, 'Rock Island Arsenal', 'IL', 'A surviving M65 ''Atomic Annie'' nuclear-capable artillery piece sits on the active arsenal as an outsized Cold War relic.', 'limited', 'https://www.aschq.army.mil/About/History/Tours/RIA/', null, 'America/Chicago', now()),
  ('Gemini Giant', 'gemini-giant', 'roadside-oddities', 41.30622, -88.14968, 'Wilmington', 'IL', 'The iconic green-suited Muffler Man has been restored and moved to South Island Park, preserving one of Illinois Route 66''s defining roadside figures.', 'open', 'https://media.enjoyillinois.com/press-releases/illinois-gears-up-for-the-route-66-centennial-in-2026-with-exciting-new-attractions-experiences-and-events/', null, 'America/Chicago', now()),
  ('Old Joliet Prison', 'old-joliet-prison', 'weird-history', 41.54572, -88.0729, 'Joliet', 'IL', 'The massive limestone prison operated from 1858 to 2002 and now offers tours through cellblocks, yards, and locations familiar from film and television.', 'limited', 'https://www.jolietprison.org/', null, 'America/Chicago', now()),
  ('Joliet Iron Works Historic Site', 'joliet-iron-works-historic-site', 'weird-history', 41.54008, -88.07932, 'Joliet', 'IL', 'Trails wind through the heavy foundations and archaeological remains of a once-enormous iron and steel complex beside the old canal corridor.', 'open', 'https://www.reconnectwithnature.org/preserves-trails/preserves/joliet-iron-works-historic-site/', null, 'America/Chicago', now()),
  ('Polk-a-Dot Drive In', 'polk-a-dot-drive-in', 'roadside-oddities', 41.26526, -88.20999, 'Braidwood', 'IL', 'A neon-heavy Route 66 diner surrounded by fiberglass figures of Elvis, Marilyn Monroe, Superman, and other oversized pop-culture characters.', 'limited', 'https://www.enjoyillinois.com/explore/listing/polk-a-dot-drive-in/', null, 'America/Chicago', now()),
  ('Gardner Two-Cell Jail', 'gardner-two-cell-jail', 'weird-history', 41.1884, -88.30471, 'Gardner', 'IL', 'A tiny 1906 two-cell jail stands beside Route 66 as a remarkably intact piece of small-town law-enforcement history.', 'open', 'https://illinoisroute66.org/', null, 'America/Chicago', now()),
  ('Gardner Streetcar Diner', 'gardner-streetcar-diner', 'weird-history', 41.1882, -88.30484, 'Gardner', 'IL', 'A restored streetcar once used as a roadside diner sits next to Gardner''s old jail and historic Route 66 alignment.', 'open', 'https://illinoisroute66.org/', null, 'America/Chicago', now()),
  ('Ambler''s Texaco Gas Station', 'amblers-texaco-gas-station', 'roadside-oddities', 41.09392, -88.43956, 'Dwight', 'IL', 'A beautifully restored 1930s gas station and visitor center preserves the look of early Route 66 automobile travel.', 'limited', 'https://www.nps.gov/places/ambler-s-texaco-gas-station.htm', null, 'America/Chicago', now()),
  ('Crazy 80''s Car Museum', 'crazy-80s-car-museum', 'museums', 41.09645, -88.43685, 'Dwight', 'IL', 'An independent collection celebrates 1980s cars, memorabilia, toys, and pop culture in a deliberately nostalgic specialty museum.', 'limited', 'https://www.enjoyillinois.com/', null, 'America/Chicago', now()),
  ('Standard Oil Gasoline Station', 'standard-oil-gasoline-station', 'roadside-oddities', 41.00191, -88.52903, 'Odell', 'IL', 'This restored 1932 filling station is one of the most photogenic surviving examples of the small service stations that lined early Route 66.', 'limited', 'https://www.nps.gov/places/standard-oil-gasoline-station.htm', null, 'America/Chicago', now()),
  ('Illinois Route 66 Hall of Fame & Museum', 'illinois-route-66-hall-of-fame-museum', 'museums', 40.88095, -88.62904, 'Pontiac', 'IL', 'A free museum packed with road signs, vehicles, memorabilia, photographs, and stories from the Illinois section of the Mother Road.', 'limited', 'https://visitpontiac.org/', null, 'America/Chicago', now()),
  ('Museum of the Gilding Arts', 'museum-of-the-gilding-arts', 'museums', 40.88155, -88.63065, 'Pontiac', 'IL', 'A museum devoted to gold and silver leaf explains gilding tools and techniques and recreates a historic gold-beating workshop.', 'limited', 'https://societyofgilders.org/museum/', null, 'America/Chicago', now()),
  ('Pontiac-Oakland Automobile Museum', 'pontiac-oakland-automobile-museum', 'museums', 40.8798, -88.62993, 'Pontiac', 'IL', 'A specialty museum devoted entirely to Pontiac and Oakland automobiles, advertising, dealer materials, engines, and related brand history.', 'limited', 'https://www.pontiacoaklandmuseum.org/', null, 'America/Chicago', now()),
  ('Route 66 Memory Lane', 'route-66-memory-lane', 'roadside-oddities', 40.65119, -88.77946, 'Lexington', 'IL', 'A preserved stretch of original Route 66 is lined with vintage billboards, Burma-Shave signs, and period roadside displays.', 'open', 'https://www.enjoyillinois.com/', null, 'America/Chicago', now()),
  ('Towanda Route 66 Parkway', 'towanda-route-66-parkway', 'roadside-oddities', 40.55902, -88.90805, 'Towanda', 'IL', 'A walking trail follows abandoned Route 66 pavement past interpretive signs, old alignments, roadside relics, and recreated historic signage.', 'open', 'http://route66towanda.org/', null, 'America/Chicago', now()),
  ('Sprague''s Super Service', 'spragues-super-service', 'roadside-oddities', 40.51753, -88.98074, 'Normal', 'IL', 'A restored 1931 Tudor Revival gas station is one of the most architecturally distinctive filling stations on Illinois Route 66.', 'limited', 'https://www.nps.gov/places/sprague-s-super-service.htm', null, 'America/Chicago', now()),
